INSERT INTO feeds (name, url) VALUES ($2::text, $1::text)
ON CONFLICT (url) DO NOTHING
RETURNING id;

SELECT id, name, enabled, consecutive_failures,
       to_char(last_success_at AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI') AS last_success
FROM feeds ORDER BY id LIMIT 40;

