const ctx = $('Parse Command').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const HELP = 'Commands:\n/addfeed &lt;url&gt; [name] - follow an RSS or Atom feed\n/feeds - list feeds and their health\n/follow Topic: keyword, keyword - set the keywords of a topic';
let out;
switch (ctx.cmd) {
  case 'denied': out = 'Not authorized. Your chat ID is ' + esc(ctx.chat_id); break;
  case 'bad': out = esc(ctx.error); break;
  case 'addfeed': out = rows.length ? '✅ Feed added (#' + rows[0].id + '): ' + esc(ctx.name) + '\nIt is fetched on the next run.' : 'That feed already exists.'; break;
  case 'follow': out = rows.length ? '✅ Topic "' + esc(ctx.topic_name) + '" saved with ' + rows[0].n + ' keywords.' : 'Could not save the topic.'; break;
  case 'feeds':
    out = rows.length ? '<b>Feeds</b>\n' + rows.map(f => (!f.enabled ? '⏸' : f.consecutive_failures >= 3 ? '⚠️' : '✅') + ' #' + f.id + ' ' + esc(f.name) +
      (f.last_success ? ' (last ok ' + esc(f.last_success) + ' UTC)' : ' (never fetched)') +
      (f.consecutive_failures ? ', ' + f.consecutive_failures + ' failures' : '')).join('\n') : 'No feeds yet. Add one with /addfeed.';
    break;
  default: out = HELP;
}
return [{ json: { chat_id: ctx.chat_id, text: out.slice(0, 3800) } }];

const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'unknown error';
const url = (e.execution && e.execution.url) || '';
return [{ json: { text: 'WORKFLOW ERROR\n\nWorkflow: ' + wf + '\nFailed node: ' + node + '\nError: ' + String(msg).slice(0, 500) + (url ? '\n' + url : '') } }];
